package com.tenora365.controller;
import com.tenora365.entity.*;import com.tenora365.repository.*;import com.tenora365.security.JwtService;import com.tenora365.service.AuthService;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.security.SecureRandom;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController{final AuthService auth;final UserRepository users;final OtpTokenRepository otps;final RefreshTokenRepository refresh;final PasswordEncoder enc;final JwtService jwt;final long otpMinutes;final com.tenora365.service.NotificationService notifications;AuthController(AuthService a,UserRepository u,OtpTokenRepository o,RefreshTokenRepository r,PasswordEncoder e,JwtService j,@Value("${app.otp.minutes}")long om,com.tenora365.service.NotificationService ns){auth=a;users=u;otps=o;refresh=r;enc=e;jwt=j;otpMinutes=om;notifications=ns;}record Login(String username,String password){}record Refresh(String refreshToken){}record ResetRequest(String username){}record Reset(String username,String otp,String newPassword){}@PostMapping("/login")public Object login(@RequestBody Login x){return auth.login(x.username(),x.password());}@GetMapping("/me")public Object me(org.springframework.security.core.Authentication a){return Map.of("username",a.getName(),"authenticated",true);}@PostMapping("/refresh")public Object refresh(@RequestBody Refresh x){String h=hash(x.refreshToken());var r=refresh.findByTokenHashAndRevokedFalse(h).orElseThrow(()->new IllegalArgumentException("Invalid refresh token"));if(r.getExpiresAt().isBefore(Instant.now()))throw new IllegalArgumentException("Refresh token expired");r.setRevoked(true);refresh.save(r);return auth.issueFor(r.getUser());}
@PostMapping("/request-otp")public Object requestOtp(@RequestBody ResetRequest x){var u=users.findByUsername(x.username()).orElseThrow(()->new IllegalArgumentException("Account not found"));String otp=String.format("%06d",new SecureRandom().nextInt(1000000));OtpToken t=new OtpToken();t.setUser(u);t.setOtpHash(hash(otp));t.setExpiresAt(Instant.now().plus(otpMinutes,java.time.temporal.ChronoUnit.MINUTES));otps.save(t);if(u.getUsername().contains("@")) notifications.email(u.getUsername(),"TENORA365 password reset OTP","Your TENORA365 OTP is: "+otp+". It expires in "+otpMinutes+" minutes."); else System.out.println("TENORA365 OTP for "+u.getUsername()+": "+otp);return Map.of("message","OTP generated and sent through the configured notification channel.");}
@PostMapping("/reset-password")public Object reset(@RequestBody Reset x){var u=users.findByUsername(x.username()).orElseThrow(()->new IllegalArgumentException("Account not found"));var t=otps.findTopByUserIdAndUsedFalseOrderByCreatedAtDesc(u.getId()).orElseThrow(()->new IllegalArgumentException("OTP not found"));if(t.getExpiresAt().isBefore(Instant.now())||!t.getOtpHash().equals(hash(x.otp())))throw new IllegalArgumentException("Invalid or expired OTP");u.setPasswordHash(enc.encode(x.newPassword()));users.save(u);t.setUsed(true);otps.save(t);refresh.deleteByUserId(u.getId());return Map.of("message","Password reset successfully");}
static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
